-- Applied 2026-10-05. Additive. Rollback: drop tables assets, subscriptions, liabilities; alter table profiles drop column country;
alter table public.profiles add column if not exists country text;
create table if not exists public.liabilities (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users on delete cascade default auth.uid(), name text not null, kind text not null default 'Personal loan', balance numeric(14,2) not null check (balance >= 0), apr numeric(6,3) not null default 0 check (apr >= 0 and apr <= 200), min_payment numeric(14,2) not null default 0 check (min_payment >= 0), created_at timestamptz default now());
create table if not exists public.subscriptions (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users on delete cascade default auth.uid(), name text not null, amount numeric(14,2) not null check (amount > 0), cycle text not null default 'monthly' check (cycle in ('weekly','monthly','quarterly','yearly')), next_renewal date not null, last_used date, status text not null default 'active' check (status in ('active','cancelled')), created_at timestamptz default now());
create table if not exists public.assets (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users on delete cascade default auth.uid(), name text not null, class text not null, value numeric(16,2) not null check (value >= 0), currency text not null default 'UGX', created_at timestamptz default now());
-- plus RLS "own rows" policy on each table (see applied migration) and index subscriptions_user_idx
